mutation {
  orderCreate(
    input: {
      lineItems: [{ variantId: "variant-id", quantity: 1 }],
      shippingAddress: { address1: "123 Main St" },
      fulfillments: {
        trackingNumbers: ["tracking-number-1", "tracking-number-2"]
      }
    }
  ) {
    order {
      id
    }
  }
}
